<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import AppShell from '../components/AppShell.vue'
import { api } from '../api'
import type { CreateUserRequest, Page, UpdateUserRequest, User, UserFilter } from '../api/types'
import { errorText } from '../utils/format'
import { Check, ChevronLeft, ChevronRight, CirclePlus, Edit3, Search, ShieldAlert, UserRound, UserRoundCheck, UserRoundX } from '@lucide/vue'
import { useAuthStore } from '../stores/auth'
const auth=useAuthStore()
const rows=ref<User[]>([]), total=ref(0), page=ref(1), pageSize=20, pages=computed(()=>Math.max(1,Math.ceil(total.value/pageSize)))
const keyword=ref(''), enabled=ref(''), loading=ref(false), actionBusy=ref(false), error=ref(''), queryError=ref('')
const modal=ref<'create'|'edit'|null>(null), selected=ref<User|null>(null), confirmUser=ref<User|null>(null)
const form=ref({username:'',password:'',fullName:'',studentNo:''}), formError=ref('')
const dialogElement=ref<HTMLElement|null>(null), returnFocus=ref<HTMLElement|null>(null)
watch([modal,confirmUser],async([modalValue,confirmValue])=>{if(modalValue||confirmValue){await nextTick();const first=dialogElement.value?.querySelector<HTMLElement>('input:not([disabled]),button:not([disabled])');first?.focus()}else{form.value.password='';await nextTick();returnFocus.value?.focus();returnFocus.value=null}})
function handleDialogKeyboard(event:KeyboardEvent){if(event.key==='Escape'){if(modal.value||confirmUser.value){event.preventDefault();modal.value=null;confirmUser.value=null}return}if(event.key!=='Tab'||(!modal.value&&!confirmUser.value))return;const root=dialogElement.value;if(!root)return;const focusable=[...root.querySelectorAll<HTMLElement>('input:not([disabled]),button:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')];if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&(document.activeElement===first||!root.contains(document.activeElement))){event.preventDefault();last.focus()}else if(!event.shiftKey&&(document.activeElement===last||!root.contains(document.activeElement))){event.preventDefault();first.focus()}}
async function load(p=1){page.value=p;loading.value=true;queryError.value='';const g=auth.generation;const f:UserFilter={keyword:keyword.value.trim()||undefined,enabled:enabled.value===''?undefined:enabled.value==='true',page:p,pageSize};try{const r:Page<User>=await api.users(f);if(g===auth.generation){rows.value=r.items;total.value=r.total;page.value=r.page}}catch(e){if(g===auth.generation)queryError.value=errorText(e)}finally{if(g===auth.generation)loading.value=false}}
function openCreate(event:MouseEvent){returnFocus.value=event.currentTarget as HTMLElement;selected.value=null;form.value={username:'',password:'',fullName:'',studentNo:''};formError.value='';modal.value='create'}
function openEdit(user:User,event:MouseEvent){returnFocus.value=event.currentTarget as HTMLElement;selected.value=user;form.value={username:user.username,password:'',fullName:user.fullName,studentNo:user.studentNo||''};formError.value='';modal.value='edit'}
function askToggle(user:User,event:MouseEvent){returnFocus.value=event.currentTarget as HTMLElement;confirmUser.value=user}
function validate(){const f=form.value;if(modal.value==='create'&&!/^[A-Za-z0-9_.-]{3,50}$/.test(f.username)){formError.value='用户名需为 3–50 位字母、数字或 . _ -';return false}if(modal.value==='create'&&(f.password.length<8||f.password.length>128)){formError.value='密码长度需为 8–128 位';return false}if(!f.fullName.trim()||f.fullName.trim().length>100){formError.value='姓名需为 1–100 个字符';return false}if(!f.studentNo.trim()||f.studentNo.trim().length>30){formError.value='学号需为 1–30 个字符';return false}formError.value='';return true}
async function save(){if(!validate())return;actionBusy.value=true;formError.value='';const g=auth.generation;try{if(modal.value==='create'){const request:CreateUserRequest={username:form.value.username.trim(),password:form.value.password,fullName:form.value.fullName.trim(),studentNo:form.value.studentNo.trim()};await api.createUser(request)}else if(selected.value){const request:UpdateUserRequest={fullName:form.value.fullName.trim(),studentNo:form.value.studentNo.trim()};await api.updateUser(selected.value.id,request)}if(g===auth.generation){modal.value=null;await load(page.value)}}catch(e){if(g===auth.generation)formError.value=errorText(e)}finally{if(g===auth.generation)actionBusy.value=false}}
async function setEnabled(user:User){actionBusy.value=true;error.value='';const g=auth.generation;try{await api.setEnabled(user.id,!user.enabled);if(g===auth.generation){confirmUser.value=null;await load(page.value)}}catch(e){if(g===auth.generation){confirmUser.value=null;error.value=errorText(e)}}finally{if(g===auth.generation)actionBusy.value=false}}
function initials(user:User){return user.fullName.trim().slice(0,1)||user.username.slice(0,1).toUpperCase()}
onMounted(()=>{window.addEventListener('keydown',handleDialogKeyboard);void load(1)})
onUnmounted(()=>window.removeEventListener('keydown',handleDialogKeyboard))
</script>
<template><AppShell><section class="page-heading"><div><span class="eyebrow">管理工作台</span><h1>用户管理</h1><p>创建学生校园卡账户，维护用户资料与账户状态。</p></div><button class="button button-primary" @click="openCreate"><CirclePlus :size="17"/> 新建用户</button></section>
  <div v-if="error" class="page-alert"><span>{{error}}</span><button class="icon-button" @click="error=''">×</button></div>
  <section class="surface-card filter-card user-filter"><div class="user-search"><label class="search-field"><Search :size="17"/><input v-model="keyword" placeholder="搜索姓名、用户名或学号" @keydown.enter="load(1)"/></label><select v-model="enabled" aria-label="账户状态"><option value="">全部状态</option><option value="true">已启用</option><option value="false">已停用</option></select><button class="button button-primary" :disabled="loading" @click="load(1)">搜索用户</button></div></section>
  <div v-if="queryError" class="page-alert"><span>{{queryError}}</span><button class="button button-small" @click="load(page)">重试</button></div>
  <section class="surface-card users-card"><div class="section-heading"><div><h2>学生账户</h2><p>共 {{total}} 位用户</p></div><span class="user-total-badge"><UserRound :size="15"/> {{total}}</span></div><div class="table-scroll"><table class="data-table users-table"><thead><tr><th>用户</th><th>学号</th><th>账户状态</th><th>注册时间</th><th class="actions-column">操作</th></tr></thead><tbody v-if="rows.length"><tr v-for="user in rows" :key="user.id"><td><div class="user-cell"><span class="user-avatar table-avatar">{{initials(user)}}</span><span><b>{{user.fullName}}</b><small>{{user.username}}</small></span></div></td><td class="muted-cell">{{user.studentNo||'—'}}</td><td><span class="status-chip" :class="user.enabled?'success':'disabled'">{{user.enabled?'已启用':'已停用'}}</span></td><td class="muted-cell">{{new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(new Date(user.createdAt))}}</td><td><div class="row-actions"><button class="text-button" :disabled="actionBusy" @click="openEdit(user,$event)"><Edit3 :size="15"/> 编辑</button><button class="text-button" :class="user.enabled?'danger-text':''" :disabled="actionBusy" @click="askToggle(user,$event)"><component :is="user.enabled?UserRoundX:UserRoundCheck" :size="15"/> {{user.enabled?'停用':'启用'}}</button></div></td></tr></tbody><tbody v-else><tr><td colspan="5"><div class="table-empty"><span v-if="loading" class="spinner"></span><span v-else>没有找到符合条件的用户</span></div></td></tr></tbody></table></div><div class="pagination"><span>第 {{page}} 页，共 {{pages}} 页</span><div><button class="button button-small" :disabled="loading||page<=1" @click="load(page-1)"><ChevronLeft :size="15"/> 上一页</button><button class="button button-small" :disabled="loading||page>=pages" @click="load(page+1)">下一页 <ChevronRight :size="15"/></button></div></div></section>
  <div v-if="modal" class="modal-backdrop" @click.self="modal=null"><section ref="dialogElement" class="modal-card" role="dialog" aria-modal="true" :aria-labelledby="'user-modal-title'"><div class="modal-head"><div><span class="eyebrow">账户资料</span><h2 id="user-modal-title">{{modal==='create'?'新建学生用户':'编辑用户资料'}}</h2></div><button class="icon-button" aria-label="关闭" @click="modal=null">×</button></div><form class="modal-form" @submit.prevent="save"><template v-if="modal==='create'"><label class="field-label" for="username">用户名</label><input id="username" v-model="form.username" autocomplete="off" placeholder="3–50 位字母、数字、点、下划线或连字符" :disabled="actionBusy"/><label class="field-label" for="new-password">初始密码</label><input id="new-password" v-model="form.password" type="password" autocomplete="new-password" placeholder="至少 8 位" :disabled="actionBusy"/></template><label class="field-label" for="full-name">姓名</label><input id="full-name" v-model="form.fullName" maxlength="100" placeholder="学生姓名" :disabled="actionBusy"/><label class="field-label" for="student-no">学号</label><input id="student-no" v-model="form.studentNo" maxlength="30" placeholder="校园学号" :disabled="actionBusy"/><p v-if="formError" class="form-alert"><span class="alert-dot"></span>{{formError}}</p><div class="modal-actions"><button type="button" class="button button-secondary" :disabled="actionBusy" @click="modal=null">取消</button><button class="button button-primary" type="submit" :disabled="actionBusy"><span v-if="actionBusy" class="spinner spinner-light"></span><Check v-else :size="16"/> {{actionBusy?'正在保存…':'保存用户'}}</button></div></form></section></div>
  <div v-if="confirmUser" class="modal-backdrop" @click.self="confirmUser=null"><section ref="dialogElement" class="modal-card confirm-card" role="alertdialog" aria-modal="true" aria-labelledby="toggle-title" aria-describedby="toggle-description"><span class="confirm-icon"><ShieldAlert :size="22"/></span><h2 id="toggle-title">{{confirmUser.enabled?'停用':'启用'}}此账户？</h2><p id="toggle-description">{{confirmUser.enabled?'停用后该学生将无法使用校园卡服务。':'启用后该学生可以继续使用校园卡服务。'}}<br/><b>{{confirmUser.fullName}}（{{confirmUser.username}}）</b></p><div class="modal-actions"><button class="button button-secondary" :disabled="actionBusy" @click="confirmUser=null">返回</button><button class="button" :class="confirmUser.enabled?'button-danger':'button-primary'" :disabled="actionBusy" @click="setEnabled(confirmUser)">{{actionBusy?'正在更新…':confirmUser.enabled?'确认停用':'确认启用'}}</button></div></section></div>
</AppShell></template>
